-- ==============================================================================
-- VITALIS CANONICAL CONSOLIDATION - PART 1 OF 19
-- Consolidated Canonical Foods: 2500 (Range 1 to 2500)
-- Safety: Backup table public.foods_backup preserved; user custom foods untouched
-- user_id: NULL (System Food Canonical Reference Catalog)
-- ==============================================================================

-- 1. Create a safe point-in-time backup of public.foods before consolidation
CREATE TABLE IF NOT EXISTS public.foods_backup AS TABLE public.foods;

-- 2. Clear un-consolidated system records (preserve all custom user-created foods where user_id IS NOT NULL)
DELETE FROM public.foods WHERE user_id IS NULL;






